import * as THREE from 'three';
import {skyRadianceParameters} from './sky-radiance.js';
import {lightmapMeshes,lightmapGeometryRevision} from './lightmap-rendering.js';
import {rayMaterialSource,rayTextureSlots,rayTexturePixels} from './ray-materials.js';
const visible=node=>{for(let at=node;at;at=at.parent)if(!at.visible)return false;return true;};
export async function lightmapSceneSnapshot(rows,targets,resolvedEnvironment=null){
 const meshes=[],lights=[],materialCache=new Map(),position=new THREE.Vector3(),normal=new THREE.Vector3(),normalMatrix=new THREE.Matrix3();
 const material=source=>{if(materialCache.has(source))return materialCache.get(source);const result=structuredClone(rayMaterialSource(source));result.bakeTextures={};for(const slot of rayTextureSlots(source)){const p=rayTexturePixels(slot.map),wrap=value=>value===THREE.RepeatWrapping?'repeat':value===THREE.MirroredRepeatWrapping?'mirror':'clamp';result.bakeTextures[slot.path]={width:p.width,height:p.height,depth:p.depth,pixels:slot.map.type===THREE.HalfFloatType?Float32Array.from(p.data,THREE.DataUtils.fromHalfFloat):p.data.slice(),float:p.float||slot.map.type===THREE.HalfFloatType,flipY:slot.map.flipY,wrapS:wrap(slot.map.wrapS),wrapT:wrap(slot.map.wrapT),wrapR:wrap(slot.map.wrapR),filter:slot.map.magFilter===THREE.NearestFilter?'nearest':'linear'};}materialCache.set(source,result);return result;};
 for(const {object,root,contribute=true}of rows){await root.userData.ready;root.updateWorldMatrix(true,true);root.traverse(node=>{if(!node.isLight||!visible(node))return;const color=node.color.toArray(),intensity=node.intensity;if(node.isDirectionalLight){const origin=node.getWorldPosition(new THREE.Vector3()),target=node.target.getWorldPosition(new THREE.Vector3());lights.push({type:'directional',direction:origin.sub(target).normalize().toArray(),color,intensity});}else if(node.isPointLight||node.isSpotLight){const value={type:node.isSpotLight?'spot':'point',position:node.getWorldPosition(new THREE.Vector3()).toArray(),color,intensity,range:node.distance,decay:node.decay};if(node.isSpotLight)Object.assign(value,{direction:node.target.getWorldPosition(new THREE.Vector3()).sub(node.getWorldPosition(new THREE.Vector3())).normalize().toArray(),angle:node.angle,penumbra:node.penumbra});lights.push(value);}});
  if(!contribute&&!targets.includes(object.id))continue;
  for(const {key,mesh}of lightmapMeshes(root,object.id)){if(!visible(mesh)||!(Array.isArray(mesh.material)?mesh.material:[mesh.material]).some(m=>m?.visible&&!m.userData?.sky&&!m.userData?.hbSky))continue;const receiver=targets.includes(object.id);if(receiver&&(mesh.isSkinnedMesh||mesh.isInstancedMesh||Object.values(mesh.geometry.morphAttributes||{}).some(v=>v.length)))throw Error('수신 메시에는 정적 기하를 사용하세요.');const geometry=mesh.userData.hbLightmapOriginalGeometry||mesh.geometry,p=geometry.getAttribute('position'),n=geometry.getAttribute('normal'),uv=geometry.getAttribute('uv'),uv1=geometry.getAttribute('uv1'),colors=geometry.getAttribute('color');if(receiver&&!uv1)throw Error(object.name+'의 UV 1을 먼저 만드세요.');const list=Array.isArray(mesh.material)?mesh.material:[mesh.material],materials=list.map(material),instances=mesh.isInstancedMesh?mesh.count:1;
   for(let instance=0;instance<instances;instance++){const world=mesh.matrixWorld.clone();if(mesh.isInstancedMesh){const matrix=new THREE.Matrix4();mesh.getMatrixAt(instance,matrix);world.multiply(matrix);}normalMatrix.getNormalMatrix(world);const allIndices=geometry.index?Array.from(geometry.index.array):Array.from({length:p.count},(_,i)=>i),start=geometry.drawRange.start||0,count=Math.min(geometry.drawRange.count,allIndices.length-start);if(start%3||count%3)throw Error('베이크 삼각형 범위를 확인하세요.');const data={vertices:[],uvs:[],indices:allIndices.slice(start,start+count),materialIndices:[]};if(n&&!mesh.isSkinnedMesh&&!mesh.morphTargetInfluences?.some(v=>v!==0))data.normals=[];if(uv1)data.uvs1=[];if(colors)data.colors=[];for(let i=0;i<p.count;i++){mesh.getVertexPosition(i,position);data.vertices.push(position.applyMatrix4(world).toArray());data.uvs.push(uv?[uv.getX(i),uv.getY(i)]:[0,0]);if(data.normals)data.normals.push(normal.fromBufferAttribute(n,i).applyMatrix3(normalMatrix).normalize().toArray());if(uv1)data.uvs1.push([uv1.getX(i),uv1.getY(i)]);if(colors)data.colors.push([colors.getX(i),colors.getY(i),colors.getZ(i)]);}for(let f=0;f<data.indices.length/3;f++)data.materialIndices.push(geometry.groups.find(g=>start+f*3>=g.start&&start+f*3<g.start+g.count)?.materialIndex||0);meshes.push({key:mesh.isInstancedMesh?key+'@'+instance:key,object:object.id,receiver,geometrySHA256:receiver?await lightmapGeometryRevision(mesh):'',data,materials,occluder:contribute,sides:list.map(m=>m.side),doubleSided:list.some(m=>m.side!==THREE.FrontSide),vertexColors:list.some(m=>m.vertexColors)});}
  }
 }
 let environment=null;const ambient=resolvedEnvironment?.ambient;if(ambient?.indirectIntensity>0){environment={color:ambient.color.slice(0,3),groundColor:ambient.groundColor.slice(0,3),intensity:ambient.indirectIntensity,rotation:ambient.source?.rotation||0};if(ambient.source){const root=rows.find(row=>row.object.id===ambient.source.object)?.root,map=root?.userData.skyEnvironment?.texture;if(!map)throw Error('HDRI가 준비되지 않았어요.');const {width,height,data}=map.image||{};if(!data||data.length!==width*height*4)throw Error('HDRI 선형 원본을 확인하세요.');const pixels=map.type===THREE.HalfFloatType?Float32Array.from(data,THREE.DataUtils.fromHalfFloat):Float32Array.from(data);if(pixels.some((v,i)=>i%4!==3&&(!Number.isFinite(v)||v<0)))throw Error('HDRI 선형 방사휘도 범위를 확인하세요.');environment.texture={width,height,pixels,float:true,filter:'linear'};}}
 if(environment&&!environment.texture&&resolvedEnvironment?.sky)environment.procedural=skyRadianceParameters(resolvedEnvironment,ambient.color);
 return{meshes,lights,environment};
}
